"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["84404"],{51659(e){e.exports=JSON.parse('{"id":"V4-149","slug":"carbon-offset","term":"Carbon Offset","also_known_as":[],"difficulty":"Intermediate","definition":"A carbon offset is a credit representing the reduction or removal of one tonne of carbon dioxide equivalent from the atmosphere, which a company or person can buy to compensate for their own emissions.","explanation":["Carbon offsets are generated by projects that reduce or remove greenhouse gas emissions, such as protecting forests, planting trees, capturing methane from landfills, providing clean cookstoves or funding renewable energy. Each verified tonne becomes a credit that can be sold.","For example, an airline might offer passengers the option of buying offsets to compensate for the emissions from their flight, funding a forest protection project.","Offsets can be traded in voluntary carbon markets, where companies buy them to meet their own climate goals, and some compliance markets, where they can be used to meet regulatory obligations.","Carbon offsets are controversial. Critics have found that many projects deliver less benefit than claimed, because the emissions reductions would have happened anyway, are temporary, such as forests that later burn, or are overestimated. Investigations into some forestry credits raised serious doubts about their value. Bodies such as the Integrity Council for the Voluntary Carbon Market have developed standards to improve quality. Most climate frameworks say companies should cut their own emissions first and use offsets only for what cannot be reduced."],"note":"","total":1725,"prev":{"slug":"carbon-footprint","term":"Carbon Footprint"},"next":{"slug":"carbon-tax","term":"Carbon Tax"}}')}}]);